    });
  });
}

/// Jitter stays within ±jitterFactor/2 (deterministic Random(42)).
void jitterDelayTests() {
  group('SyncRetryPolicy delay math', () {
    test('jitter stays within ±jitterFactor/2 of the delay', () {
      final jittered = SyncRetryPolicy(
        maxAttempts: 8,
        baseDelayMs: 10000,
