                long delay = resetTime - currentTime;
                // Honor the server's reset time capped by rateLimitMaxWaitSeconds
                long maxWaitMs = rateLimitMaxWaitSeconds * 1000L;
                long waitMs = delay + 1000L; // Add 1 second buffer
                if (waitMs > maxWaitMs) {
                    logger.warn(...);
                    waitMs = maxWaitMs;
                }
                logger.info("Rate limit resets at: {}, waiting {} ms", resetTime, waitMs);
                return waitMs;
            }
        } catch (NumberFormatException e) {
            logger.debug(...);
        }
    }

    // Exponential backoff with jitter
    long delay = (long) (baseDelayMs * Math.pow(backoffMultiplier, attemptNumber - 1));
    delay = Math.min(delay, maxDelayMs);
    return addJitter(delay);
}
