  factory SyncRetryPolicy.forUrl(
    String url, {
    String? Function(String key)? get,
    Random? random,
  }) {
    final cloud = get?.call('JIRA_CLOUD')?.toLowerCase() == 'true' ||
        url.contains('atlassian.net');
