          .statusDelayMs(1, {'X-RateLimit-Reset': '${resetSecondsFromNow(600)}'});
      // ~600s + 1s buffer; maxDelayMs is 60s and must not cap it.
      expect(delay, greaterThan(policy.maxDelayMs));
      expect(delay, inInclusiveRange(595000, 602000));
    });

