        () {
      final delay = policy.statusDelayMs(1, const {'Retry-After': '7200'}, 429);
      final capMs = SyncRetryPolicy.defaultRateLimitMaxWaitSeconds * 1000;
      expect(delay, inInclusiveRange(capMs * 0.84, capMs * 1.16));
