  /// tuning — more attempts, longer cap, wider jitter.
  factory SyncRetryPolicy.forJiraCloud([Random? random]) => SyncRetryPolicy(
        maxAttempts: 7,
        baseDelayMs: 2000,
        maxDelayMs: 120000,
        backoffMultiplier: 2.0,
        jitterFactor: 0.4,
        random: random ?? Random(),
