              baseDelayMs: _intEnv(get, 'JIRA_RETRY_BASE_DELAY_MS', 1000),
              maxDelayMs: _intEnv(get, 'JIRA_RETRY_MAX_DELAY_MS', 60000),
              backoffMultiplier:
