    if (server == null) return null; // Retry-After over the cap: abort
    if (server.ms > 0) return server.jittered ? _addJitter(server.ms) : server.ms;
    return _addJitter(
      min(
        maxDelayMs,
        (baseDelayMs * pow(backoffMultiplier, attempt - 1)).toInt(),
      ),
    );
  }

