      }
    });

    test('default rate-limit max wait is 3600 seconds', () {
      expect(SyncRetryPolicy.defaultRateLimitMaxWaitSeconds, 3600);
      expect(policy.rateLimitMaxWaitSeconds, 3600);
    });
  });
}
