  factory SyncRetryPolicy.fromEnvMap(String? Function(String) get,
          [Random? random]) =>
      (get('JIRA_RETRY_ENABLED')?.toLowerCase() == 'false')
          ? const SyncRetryPolicy(
              maxAttempts: 0,
              baseDelayMs: 0,
              maxDelayMs: 0,
              backoffMultiplier: 1.0,
              jitterFactor: 0.0,
            )
